# Bag-size presets (lb per bag) so parents don't have to type pack sizes.
BAG_SIZE_PRESETS = {
    "rice": 5,
    "flour": 5,
}


def bag_preset(name: str) -> float:
    """Return the lb-per-bag preset for a known bulk item."""
